const characters = [{"id":1,"caseName":"attached-universal-strong","platform":"Universal","strength":"Strong","sourceLabel":"user attachment: Strong Filmic Continuity"},{"id":2,"caseName":"attached-universal-subtle","platform":"Universal","strength":"Subtle","sourceLabel":"user attachment: Subtle Cinematic Realism"},{"id":3,"caseName":"attached-universal-heavy","platform":"Universal","strength":"Heavy","sourceLabel":"user attachment: Heavy Muted Arthouse"}];

function envelope(data) { return [{ result: { data: { json: data } } }]; }
function send(res, status, body) { res.statusCode = status; res.setHeader("content-type", "application/json; charset=utf-8"); res.setHeader("access-control-allow-origin", "*"); res.end(JSON.stringify(body)); }
export default function handler(req, res) {
  const path = String(req.url || "").split("?")[0];
  const procedures = path.split("/api/trpc/")[1] || "";
  const names = procedures.split(",").filter(Boolean);
  const result = names.map((name) => {
    if (name === "filmGrab.list") return films;
    if (name === "characterPrompts.list") return characters;
    if (name === "filmGrab.sync" || name === "filmGrab.syncLatest" || name === "characterPrompts.sync") return { synced: 0, source: "public-seed-fallback" };
    return null;
  });
  if (!names.length || result.some((value) => value === null)) return send(res, 404, { error: "Public procedure not found" });
  send(res, 200, envelope(result.length === 1 ? result[0] : result));
}
